on increaseApproval(address _spender, uint _addedValue) public whenNotPaused { return super.increaseApproval(_spender, _addedValue); } function decreaseApproval(address _spender, uint _subtractedValue) public whenNotPaused { return super.decreaseApproval(_spender, _subtractedValue); } } contract NewIntelTechMedia is PausableToken { using SafeMath for uint256; string public constant name = "NewIntelTechMedia"; string public constant symbol = "NETM"; uint256 public constant decimals = 18; function NewIntelTechMedia(address _owner) public { totalSupply = 500000000000000000000000000; owner = _owner; paused = false; balances[owner] = totalSupply; Transfer(address(0), owner, totalSupply); } }

